definition.script:
pipeline {
  agent any
  stages {
    stage('Deploy Operations Service') {
      steps {
        build job: 'PIC-SURE Wildfly Stack Deploy', parameters: [
          [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
          [$class: 'StringParameterValue', name: 'TARGET_STACK', value: params.TARGET_STACK],
          [$class: 'BooleanParameterValue', name: 'DEPLOY_OPERATIONS', value: true],
          [$class: 'BooleanParameterValue', name: 'BANNER_ROLLOUT', value: params.BANNER_ROLLOUT],
          [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_TUPLE_SHA256', value: params.BANNER_ROLLOUT_TUPLE_SHA256]
        ]
      }
    }
  }
}
